-- public.record_aux_list_failure(p_list text)
CREATE OR REPLACE FUNCTION public.record_aux_list_failure(p_list text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  n integer;
begin
  -- PERF1 (CGR-272): one failed load of an auxiliary hint list, counted per team of the caller and Zurich day.
  -- Team level only: no person, no request detail is stored. A display aid, never a rule input.
  if private.access_ended((select auth.uid())) then return 0; end if;  -- LEAVE1-3
  if p_list is null or p_list not in ('team_visit_alerts') then
    raise exception 'aux_list_unknown' using errcode = '22023';
  end if;
  insert into private.aux_list_failures as f (team_id, day, list_key, failures, last_at)
  select distinct tm.team_id, (private.at_zurich(private.now()))::date, p_list, 1, private.now()
  from public.team_memberships tm
  where tm.user_id = (select auth.uid())
  on conflict (team_id, day, list_key) do update set failures = f.failures + 1, last_at = excluded.last_at;
  get diagnostics n = row_count;
  return n;
end
$function$;

revoke all on function public.record_aux_list_failure(p_list text) from public, anon, authenticated, service_role;
grant execute on function public.record_aux_list_failure(p_list text) to authenticated;
comment on function public.record_aux_list_failure(p_list text) is 'PERF1 (CGR-272): counts one failed load of an auxiliary hint list (team_visit_alerts) per team of the caller and Zurich day in private.aux_list_failures. Team level only, never per person. Returns the number of team rows counted.';
